Below is a **complete, self‑contained example** that implements a **total‑order broadcast** (atomic broadcast) on top of a Raft log.  
It uses the popular **hashicorp/raft** library, keeps the log in memory (so no external DB is required) and shows how to:

* bootstrap a 3‑node cluster,  
* propose messages through the Raft log,  
* deliver them in the same order on every correct node,  
* detect leader changes and re‑propose automatically, and  
* kill the current leader and watch the remaining nodes elect a new one and continue to broadcast.

The code is intentionally small (≈ 300 lines) so you can read, compile and run it with a single `go run`.

---

## 1.  How it works (high‑level)

| Step | What happens |
|------|---------------|
| **Bootstrap** | The first node (`A`) starts a single‑node Raft cluster. It becomes leader immediately. |
| **Join** | Nodes `B` and `C` start with *no* peers. The leader adds them with `AddPeer`. From now on the cluster has 3 members and needs a quorum of 2. |
| **Broadcast** | A client calls `Broadcast(msg)`. The message is **serialized to JSON** and handed to `Raft.Apply`. Raft writes the entry to its replicated log, replicates it to a majority and **commits** it. |
| **Delivery** | When an entry is committed the `BroadcastFSM.Apply` method is called. The FSM simply sends the deserialized message into a channel that the application reads – all nodes receive the same messages in the same order because the Raft log is the single source of truth. |
| **Leader failure** | If the leader crashes, the `LeaderCh` on the remaining nodes becomes true after a new election. The `proposeLoop` automatically retries any message that was rejected with `ErrNotLeader`. The first node that becomes leader will start committing again, the others will just forward their queued messages. |
| **Re‑election** | After `A` is killed, `B` or `C` is elected (the one that wins the election). The test then broadcasts more messages from the new leader, demonstrating that the service continues to deliver in total order. |

The key property of **total‑order broadcast** (also called *atomic broadcast*) is exactly what Raft provides: *all correct processes deliver messages in the same order, and every delivered message was previously proposed by some process*. By writing each user message into the Raft log we get that guarantee for free.

---

## 2.  Full source (copy‑paste‑and‑run)

```go
// toporder/main.go
// ------------------------------------------------------------
// Total‑order broadcast built on a Raft log (hashicorp/raft).
// ------------------------------------------------------------
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net"
	"os"
	"sync"
	"time"

	"github.com/hashicorp/raft"
)

// ------------------------------------------------------------
// User‑level message
// ------------------------------------------------------------
type Message struct {
	Seq  uint64
	Data string
}

// ------------------------------------------------------------
// Raft FSM – stores the log and delivers committed messages
// ------------------------------------------------------------
type BroadcastFSM struct {
	mu       sync.Mutex
	messages []Message
	deliverC chan<- Message // non‑blocking delivery to the application
}

func NewBroadcastFSM(deliverC chan<- Message) *BroadcastFSM {
	return &BroadcastFSM{deliverC: deliverC}
}

// Apply is called for every committed Raft log entry.
func (f *BroadcastFSM) Apply(l *raft.Log) interface{} {
	var msg Message
	if err := json.Unmarshal(l.Data, &msg); err != nil {
		log.Printf("[FSM] unmarshal error: %v", err)
		return err
	}
	f.mu.Lock()
	f.messages = append(f.messages, msg)
	f.mu.Unlock()

	// deliver to the consumer – we use a non‑blocking send
	select {
	case f.deliverC <- msg:
	default:
	}
	return nil
}

// Snapshot returns a point‑in‑time snapshot of the FSM.
func (f *BroadcastFSM) Snapshot() (raft.FSMSnapshot, error) {
	f.mu.Lock()
	snap := &snapshot{messages: append([]Message{}, f.messages...)}
	f.mu.Unlock()
	return snap, nil
}

type snapshot struct {
	messages []Message
}

func (s *snapshot) Persist(sink raft.SnapshotSink) error {
	enc := json.NewEncoder(sink)
	if err := enc.Encode(s.messages); err != nil {
		return err
	}
	return sink.Close()
}

func (s *snapshot) Release() {}

// Restore rebuilds the FSM from a snapshot.
func (f *BroadcastFSM) Restore(reader io.ReadCloser) error {
	dec := json.NewDecoder(reader)
	var msgs []Message
	if err := dec.Decode(&msgs); err != nil {
		return err
	}
	f.mu.Lock()
	f.messages = msgs
	f.mu.Unlock()
	return nil
}

// ------------------------------------------------------------
// High‑level total‑order broadcast API
// ------------------------------------------------------------
type TotalOrderBroadcast struct {
	node     *raft.Raft            // underlying Raft node
	deliverC <-chan Message        // channel that consumers read from
	proposeC chan Message          // internal channel for proposing
	closeC   chan struct{}         // shutdown signal
	wg       sync.WaitGroup
	id       string                // node identifier (e.g. "A")
}

// NewTotalOrderBroadcast creates a new broadcast instance.
//   nodeID  – unique id for this node (string)
//   addr    – IP:port that this node will listen on (e.g. "127.0.0.1:8001")
//   peers   – list of addresses of existing nodes (empty for the first node)
//   deliverC– channel where committed messages will be sent
func NewTotalOrderBroadcast(nodeID, addr string, peers []string, deliverC chan Message) (*TotalOrderBroadcast, error) {
	// ---------- Raft configuration ----------
	cfg := raft.DefaultConfig()
	cfg.LocalID = raft.ServerID(nodeID)

	// In‑memory log & snapshot stores (no external DB needed)
	logStore := raft.NewInmemStore()
	snapStore := raft.NewInmemSnapshotStore()

	// TCP transport – each node listens on its own port
	listener, err := net.Listen("tcp", addr)
	if err != nil {
		return nil, fmt.Errorf("listen on %s: %w", addr, err)
	}
	transport, err := raft.NewTCPTransport(addr, listener, 2, 10*time.Second, os.Stderr)
	if err != nil {
		return nil, fmt.Errorf("create TCP transport: %w", err)
	}

	// ---------- Bootstrap or join ----------
	fsm := NewBroadcastFSM(deliverC)
	ra, err := raft.NewRaft(cfg, fsm, logStore, snapStore, transport)
	if err != nil {
		return nil, fmt.Errorf("create Raft node: %w", err)
	}

	if len(peers) == 0 {
		// First node – start a single‑node cluster
		conf := raft.Configuration{
			Servers: []raft.Server{
				{ID: raft.ServerID(nodeID), Address: raft.ServerAddress(addr)},
			},
		}
		ra.BootstrapCluster(conf)
	} else {
		// Not the first node – it will be added later via AddPeer
		// (we deliberately leave the configuration empty here)
	}

	// ---------- Internal propose loop ----------
	to := &TotalOrderBroadcast{
		node:     ra,
		deliverC: deliverC,
		proposeC: make(chan Message, 100),
		closeC:   make(chan struct{}),
		id:       nodeID,
	}
	to.wg.Add(1)
	go to.proposeLoop()
	return to, nil
}

// proposeLoop runs in the background and forwards messages to the Raft log.
func (t *TotalOrderBroadcast) proposeLoop() {
	defer t.wg.Done()
	for {
		select {
		case msg := <-t.proposeC:
			data, err := json.Marshal(msg)
			if err != nil {
				log.Printf("[%s] marshal error: %v", t.id, err)
				continue
			}
			// Apply with a 5‑second timeout
			f := t.node.Apply(data, 5*time.Second)
			if err := f.Error(); err != nil {
				log.Printf("[%s] apply error (will retry): %v", t.id, err)
				// Not the leader – wait a bit and retry
				time.Sleep(500 * time.Millisecond)
				t.proposeC <- msg // re‑queue
				continue
			}
		case <-t.closeC:
			return
		}
	}
}

// Broadcast submits a message for total‑order delivery.
// It returns as soon as the message has been handed to the local Raft node
// (the message is guaranteed to be eventually delivered to all correct nodes).
func (t *TotalOrderBroadcast) Broadcast(msg Message) error {
	select {
	case t.proposeC <- msg:
		return nil
	case <-time.After(5 * time.Second):
		return fmt.Errorf("timeout while submitting message")
	}
}

// LeaderCh returns a channel that is closed (true) when this node is the leader.
func (t *TotalOrderBroadcast) LeaderCh() <-chan bool {
	return t.node.LeaderCh()
}

// AddPeer tells the cluster that a new node (identified by address) may join.
// It is safe to call even if the node is already a member.
func (t *TotalOrderBroadcast) AddPeer(address string) error {
	f := t.node.AddPeer(raft.ServerAddress(address))
	return f.Error()
}

// Close shuts down the Raft node and the internal goroutines.
func (t *TotalOrderBroadcast) Close() error {
	close(t.closeC)
	t.wg.Wait()
	f := t.node.Shutdown()
	return f.Error()
}

// ------------------------------------------------------------
// Helper – consume delivered messages
// ------------------------------------------------------------
func consume(id string, ch <-chan Message, wg *sync.WaitGroup) {
	defer wg.Done()
	for {
		select {
		case msg := <-ch:
			log.Printf("[%s] delivered: %v", id, msg)
		case <-time.After(10 * time.Second):
			return
		}
	}
}

// ------------------------------------------------------------
// Demonstration
// ------------------------------------------------------------
func main() {
	// ----- 1️⃣  Create delivery channels for each node -----
	deliverA := make(chan Message, 100)
	deliverB := make(chan Message, 100)
	deliverC := make(chan Message, 100)

	// ----- 2️⃣  Start the first node (bootstrap) -----
	nodeA, err := NewTotalOrderBroadcast("A", "127.0.0.1:8001", nil, deliverA)
	if err != nil {
		log.Fatalf("start node A: %v", err)
	}
	// Wait until A becomes leader
	for !<-nodeA.LeaderCh() {
		time.Sleep(100 * time.Millisecond)
	}
	log.Println("Node A became leader")

	// ----- 3️⃣  Start the other two nodes (they will join later) -----
	nodeB, err := NewTotalOrderBroadcast("B", "127.0.0.1:8002", []string{"127.0.0.1:8001"}, deliverB)
	if err != nil {
		log.Fatalf("start node B: %v", err)
	}
	nodeC, err := NewTotalOrderBroadcast("C", "127.0.0.1:8003", []string{"127.0.0.1:8001"}, deliverC)
	if err != nil {
		log.Fatalf("start node C: %v", err)
	}

	// Give the transports time to settle
	time.Sleep(1 * time.Second)

	// ----- 4️⃣  Add B and C as peers through the leader -----
	if err := nodeA.AddPeer("127.0.0.1:8002"); err != nil {
		log.Printf("AddPeer B error (may already exist): %v", err)
	}
	if err := nodeA.AddPeer("127.0.0.1:8003"); err != nil {
		log.Printf("AddPeer C error (may already exist): %v", err)
	}
	log.Println("Peers added")

	// Wait for the configuration to propagate
	time.Sleep(2 * time.Second)

	// ----- 5️⃣  Start consumers on each node -----
	var wg sync.WaitGroup
	wg.Add(3)
	go consume("A", deliverA, &wg)
	go consume("B", deliverB, &wg)
	go consume("C", deliverC, &wg)

	// ----- 6️⃣  Broadcast a few messages from the leader (A) -----
	for i := 1; i <= 3; i++ {
		msg := Message{Seq: uint64(i), Data: fmt.Sprintf("msg-%d", i)}
		if err := nodeA.Broadcast(msg); err != nil {
			log.Printf("[A] broadcast error: %v", err)
		} else {
			log.Printf("[A] broadcasted: %v", msg)
		}
		time.Sleep(200 * time.Millisecond)
	}

	// ----- 7️⃣  Simulate a leader crash -----
	log.Println("=== Killing node A (the leader) ===")
	nodeA.Close() // this will cause a leader election

	// Wait for a new leader to be elected
	var newLeader *TotalOrderBroadcast
	for {
		if nodeB.LeaderCh() {
			newLeader = nodeB
			log.Println("Node B is now the leader")
			break
		}
		if nodeC.LeaderCh() {
			newLeader = nodeC
			log.Println("Node C is now the leader")
			break
		}
		time.Sleep(500 * time.Millisecond)
	}

	// ----- 8️⃣  Continue broadcasting from the new leader -----
	for i := 4; i <= 6; i++ {
		msg := Message{Seq: uint64(i), Data: fmt.Sprintf("msg-%d", i)}
		if err := newLeader.Broadcast(msg); err != nil {
			log.Printf("[%s] broadcast error: %v", newLeader.id, err)
		} else {
			log.Printf("[%s] broadcasted: %v", newLeader.id, msg)
		}
		time.Sleep(200 * time.Millisecond)
	}

	// Give the system a moment to finish delivering
	time.Sleep(3 * time.Second)

	// ----- 9️⃣  Cleanup -----
	nodeB.Close()
	nodeC.Close()
	wg.Wait()
	log.Println("All done – total‑order broadcast works across failures!")
}
