    if err != nil {
        log.Fatalf("failed to create node C: %v", err)
    }
    defer nodeC.Close()

    // Allow some time for cluster to settle.
    time.Sleep(2 * time.Second)

    // Broadcast some messages from node A (leader).
    for i := 1; i <= 5; i++ {
        msg := Message{Seq: uint64(i), Data: fmt.Sprintf("msg-%d", i)}
        if err := nodeA.Broadcast(msg); err != nil {
            log.Printf("broadcast error: %v", err)
        }
        time.Sleep(100 * time.Millisecond)
    }

    // Consume delivered messages on each node.
    var wg sync.WaitGroup
    wg.Add(3)
    go func() {
        defer wg.Done()
        for {
            select {
            case msg := <-deliverA:
                log.Printf("[A] delivered: %v", msg)
            case <-time.After(10 * time.Second):
                return
            }
        }
    }()
    go func() {
        defer wg.Done()
        for {
            select {
            case msg := <-deliverB:
                log.Printf("[B] delivered: %v", msg)
            case <-time.After(10 * time.Second):
                return
            }
        }
    }()
    go func() {
        defer wg.Done()
        for {
            select {
            case msg := <-deliverC:
                log.Printf("[C] delivered: %v", msg)
            case <-time.After(10 * time.Second):
                return
            }
        }
    }()

    wg.Wait()
}

