type BroadcastFSM struct {
    mu sync.Mutex
    msgs []Message
    deliverC chan<- Message
}

func (f *BroadcastFSM) Apply(log *raft.Log) interface{} {
    var msg Message
    if err := json.Unmarshal(log.Data, &msg); err != nil {
        return err
    }
    f.mu.Lock()
    f.msgs = append(f.msgs, msg)
    f.mu.Unlock()
    // non-blocking send to delivery channel
    select {
    case f.deliverC <- msg:
    default:
        // if channel full, drop (should not happen)
    }
    return nil
}
```

Implement Snapshot:

```
func (f *BroadcastFSM) Snapshot() (raft.FSMSnapshot, error) {
    f.mu.Lock()
    copy := make([]Message, len(f.msgs))
    copy = append(copy, f.msgs...)
    f.mu.Unlock()
    return &snapshot{messages: copy}, nil
}
```

Implement snapshot:

