func NewTotalOrderBroadcast(nodeID, addr string, peers []string, deliverC chan Message) (*TotalOrderBroadcast, error) {
    config := raft.DefaultConfig()
    config.LocalID = raft.ServerID(nodeID)

    // Use in-memory stores
    logStore := raft.NewInmemStore()
    snapshotStore := raft.NewInmemSnapshotStore()

    // Create TCP transport
    listener, err := net.Listen("tcp", addr)
    if err != nil {
        return nil, fmt.Errorf("listen on %s: %w", addr, err)
    }

    transport, err := raft.NewTCPTransport(addr, listener, 2, 10*time.Second, os.Stderr)
    if err != nil {
        return nil, fmt.Errorf("create transport: %w", err)
    }

    // Create FSM
    fsm := &BroadcastFSM{
        deliverC: deliverC,
    }

    // Create Raft instance
    r, err := raft.NewRaft(config, fsm, logStore, snapshotStore, transport)
    if err != nil {
        return nil, fmt.Errorf("create raft: %w", err)
    }

    // Bootstrap or join
    if len(peers) == 0 {
        // This node is the first in the cluster
        configuration := raft.Configuration{
            Servers: []raft.Server{
                {ID: raft.ServerID(nodeID), Address: raft.ServerAddress(addr)},
            },
        }
        r.BootstrapCluster(configuration)
    } else {
        // For joining nodes, we will add peers later via leader.
        // No-op here.
    }

    to := &TotalOrderBroadcast{
        node:     r,
        deliverC: deliverC,
        proposeC: make(chan Message, 100),
        closeC:   make(chan struct{}),
        id:       nodeID,
    }

    to.wg.Add(1)
    go to.proposeLoop()

    return to, nil
}
```

